 return pageTop('Производство','Обеспечение заказов, наряды и свободный выпуск на склад.',btn('＋ Выпуск на склад','new-production','primary')+(!active?btn('Передать наряд в работу','new-job'):''))+
 `<div class="toolbar"><label class="field">План на дату<input id="plan-date" type="date" value="${planDate}"></label>${printLink('plan','','Печать потребности','&date='+planDate)}</div>`+
 (p.prior_uncovered.length?`<div class="notice">Есть необеспеченные более ранние заказы. Проверьте производство на даты: ${[...new Set(p.prior_uncovered.map(a=>a.due.slice(0,10)))].map(dt=>btn(fmtDate(dt),'plan-day','small',`data-date="${dt}"`)).join(' ')}</div>`:'')+card('Обеспечение заказов',p.products.length?table(['Продукция','Заказано всего','Отгружено','Обеспечено складом','Не хватает','План с запасом',''],p.products.map(r=>`<tr><td><strong>${esc(r.name)}</strong>${r.error?`<small class="text-red">${esc(r.error)}</small>`:''}</td><td>${num(r.total_ordered)} ${esc(r.unit)}${r.remaining_portions?'<small>В открытых заказах: '+num(r.remaining_portions)+' порц.</small>':''}</td><td>${num(r.shipped)}</td><td>${num(r.covered)}</td><td>${r.shortage>0?badge(num(r.shortage),'amber'):badge('Обеспечено')}</td><td><strong>${num(r.produce)}</strong><small>Запас ${num(r.buffer)}%</small></td><td>${btn('Выпуск','new-production','small',`data-id="${r.item_id}" data-qty="${r.produce||1}" ${active?.products.some(x=>x.item_id===r.item_id)?`data-job="${active.id}"`:''}`)}</td></tr>`)):empty('На эту дату заказов нет','Можно выпустить на свободный склад.'))+
 `<p class="help">Остатки распределены однократно по дате и времени доставки, с учётом ранних заказов и срока годности. Обеспечение порционных заказов оценивается по среднему весу; фактическое число порций подтверждается при отгрузке. Изменения пересчитываются при сохранении заказа и выпуска. Запас производства не увеличивает счёт клиента.</p>`+
 p.jobs.map(j=>card(`Наряд № ${j.id} · ${j.status==='active'?'В работе':'Закрыт'}`,table(['Продукция','План наряда','Выпущено','Осталось по наряду','Сейчас требуется','Изменение'],j.progress.map(r=>`<tr><td>${esc(r.name)}</td><td>${num(r.qty)} ${esc(r.unit)}${r.portions?'<small>В заказах: '+num(r.portions)+' порц.</small>':''}</td><td>${num(r.produced)}</td><td>${num(r.remaining)}</td><td>${num(r.current)}</td><td>${Math.abs(r.change)>1e-6?badge((r.change>0?'Добавлено +':'Уменьшено ')+num(r.change),r.change>0?'amber':'gray'):'—'}</td></tr>`)),printLink('job',j.id,'Печать наряда')+btn('История','view-job-history','small',`data-id="${j.id}"`)+(j.status==='active'?btn('Принять изменения','review-job','small',`data-id="${j.id}"`)+btn('Закрыть наряд','close-job','small',`data-id="${j.id}"`):''))).join('')+
 card('Расшифровка по заказам',p.orders.length?table(['Заказ / покупатель','Время / водитель','Продукция','Осталось отгрузить','Обеспечено','Нужно изготовить'],p.orders.map(a=>`<tr><td>№ ${a.order_id} · ${esc(partner(a.client_id)?.name)}</td><td>${fmtDate(a.due)}<small>${esc(S.drivers.find(d=>d.id===a.driver_id)?.name||'Водитель не назначен')}</small></td><td>${esc(item(a.item_id)?.name)}</td><td>${num(a.remaining)} ${esc(item(a.item_id)?.unit)}${a.remaining_portions?'<small>'+num(a.remaining_portions)+' порц.</small>':''}</td><td>${num(a.covered)}</td><td>${num(a.shortage)}</td></tr>`)):empty('Нет открытых заказов'))+
 card('Потребность в сырье',p.ingredients.length?table(['Ингредиент','Требуется','Доступно сейчас','Не хватает'],p.ingredients.map(r=>`<tr><td>${esc(r.name)}</td><td>${num(r.qty)} ${esc(r.unit)}</td><td>${num(r.available)}</td><td>${r.shortage>0?badge(num(r.shortage),'red'):badge('Достаточно')}</td></tr>`)):empty('Дополнительное сырьё не требуется'))+
 card('Последние выпуски',documentRows(S.documents.filter(d=>d.kind==='production').slice(-10).reverse()));
