function documentRows(rows,includeDeleted=false){rows=rows.filter(d=>includeDeleted||(!d.data.deleted&&!d.data.deletion));return rows.length?table(['Документ','Дата','Ответственный','Сумма / себестоимость',''],rows.map(d=>`<tr><td><button type="button" class="text-button" data-action="inspect-document" data-id="${d.id}">${esc(docKinds[d.kind])} № ${d.id}</button> ${d.data.deleted?badge('Удалён','red'):d.reversed?badge('Отменён','red'):''}<small>${esc(d.kind==='expense'?(d.data.category+' · '+(d.data.purpose||d.note||'Назначение не указано')):(d.data.name||d.data.client_name||d.data.supplier_name||d.data.category||''))}</small></td><td>${fmtDate(d.date)}</td><td>${esc(d.responsible)}</td><td>${rub(['production','writeoff','inventory'].includes(d.kind)?d.cost:d.total)}</td><td>${btn('Открыть','view-document','small',`data-id="${d.id}"`)} ${!d.data.deleted&&d.kind!=='reversal'?btn('Удалить','delete-document','small danger',`data-id="${d.id}" aria-label="Удалить документ № ${d.id}"`):''}</td></tr>`)):empty('Документов пока нет','Проведённые операции появятся здесь.');}
