function analytics(){
 const docs=effectiveDocs().filter(d=>d.date>=report.from&&d.date<=report.to);const sales=docs.filter(d=>['shipment','return'].includes(d.kind));const revenue=sales.reduce((s,d)=>s+(d.kind==='return'?-1:1)*d.total,0);const cost=sales.reduce((s,d)=>s+(d.kind==='return'?-1:1)*d.cost,0);const expenses=docs.filter(d=>d.kind==='expense'&&!d.data.already_in_cost).reduce((s,d)=>s+d.total,0);const exchangeCost=docs.filter(d=>d.kind==='exchange').reduce((s,d)=>s+d.cost,0);const writeoffs=docs.filter(d=>d.kind==='writeoff').reduce((s,d)=>s+d.cost,0);const result={};
 for(const d of sales)for(const l of d.data.lines){const sign=d.kind==='return'?-1:1;const label=report.group==='product'?l.name:report.group==='client'?d.data.client_name:d.date;const key=label+'|'+l.unit;const r=result[key]??={label,unit:l.unit,qty:0,revenue:0,cost:0};r.qty+=sign*l.qty;r.revenue+=sign*(l.line_total??l.qty*l.price);r.cost+=sign*l.lots.reduce((s,x)=>s+x.qty*x.unit_cost,0);r.profit=r.revenue-r.cost;}
 const rows=Object.values(result).sort((a,b)=>b.revenue-a.revenue);const col={qty:'Количество',revenue:'Выручка',cost:'Себестоимость',profit:'Валовая прибыль'};const extra=`&from=${report.from}&to=${report.to}&group=${report.group}&columns=${report.columns.join(',')}`;
 return pageTop('Аналитика','Продажи, закупочные цены и результат производства на основе проведённых документов.',btn('Финансовые итоги за период','financial-report'))+
 `<div class="toolbar"><label class="field">С даты<input type="date" id="report-from" value="${report.from}"></label><label class="field">По дату<input type="date" id="report-to" value="${report.to}"></label><label class="field">Группировка<select id="report-group">${[['product','По продукции'],['client','По клиентам'],['day','По дням']].map(([k,v])=>`<option value="${k}" ${report.group===k?'selected':''}>${v}</option>`).join('')}</select></label></div>`+
 `<div class="metrics">${metric('Выручка',rub(revenue),'По отгрузкам за период',true)}${metric('Валовая прибыль',rub(revenue-cost),'Выручка − стоимость отгрузок')}${metric('Расходы и списания',rub(expenses+writeoffs+exchangeCost),'Расходы + списания + обмены')}${metric('Результат периода',rub(revenue-cost-expenses-writeoffs-exchangeCost),'До прочих корректировок')}</div>`+
 `<div class="report-options">${Object.entries(col).map(([k,v])=>`<label class="checkbox-field"><input type="checkbox" data-column="${k}" ${report.columns.includes(k)?'checked':''}>${v}</label>`).join('')}</div>`+
 card('Отчёт о продажах',rows.length?table(['Группа','Ед.',...report.columns.map(k=>col[k])],rows.map(r=>`<tr><td><strong>${esc(r.label)}</strong></td><td>${esc(r.unit)}</td>${report.columns.map(k=>`<td>${k==='qty'?num(r[k]):rub(r[k])}</td>`).join('')}</tr>`)):empty('Нет продаж за период','Проведите отгрузку или измените даты отчёта.'),exportButtons('analytics','',extra))+
 fullCostReport(docs)+card('История закупочных цен',table(['Дата','Сырьё','Поставщик','Цена за базовую единицу','Количество'],docs.filter(d=>d.kind==='receipt').reverse().flatMap(d=>d.data.lines.map(l=>`<tr><td>${fmtDate(d.date)}</td><td>${esc(l.name)}</td><td>${esc(d.data.supplier_name)}</td><td>${rub(l.price)} / ${esc(l.unit)}</td><td>${num(l.qty)} ${esc(l.unit)}</td></tr>`))),exportButtons('purchase_prices','',extra));
}
const describeCounts=c=>`Номенклатура: ${c.items}, контрагенты: ${c.partners}, ТТК: ${c.recipes}, партии: ${c.lots}, заказы: ${c.orders}, документы: ${c.documents}, водители: ${c.drivers||0}, сотрудники: ${c.employees||0}, наряды: ${c.production_jobs||0}`;
function settings(){return (lastRestore?`<div class="notice green" id="restore-result"><strong>Открыта восстановленная база</strong><br>${esc(describeCounts(lastRestore.counts))}<br>${esc(lastRestore.database_path)}</div>`:'')+pageTop('База и настройки','Локальное хранение, резервные копии и безопасное восстановление.',btn('Реквизиты отправителя','edit-company'))+card('Какая база открыта',`<div class="card-body"><p><strong>Файл базы:</strong> ${esc(S.runtime?.database_path||'Сервер не сообщает путь — перезапустите последнюю версию программы')}</p><p><strong>Папка программы:</strong> ${esc(S.runtime?.program_directory||'—')}</p><p>Сервер ${esc(S.runtime?.app_version||'старой версии')} · процесс ${esc(S.runtime?.pid||'—')} · запущен ${esc(S.runtime?.started_at||'—')}</p><p>Номенклатура: ${S.items.length} · контрагенты: ${S.partners.length} · заказы: ${S.orders.length} · документы: ${S.documents.length}</p><p class="help">Если путь не совпадает с вашей прежней папкой data, ничего не удаляйте. Diagnose.bat находит доступные базы и копии без изменения данных.</p></div>`)+card('Кто отгружает',`<div class="card-body"><strong>${esc(S.company.name)}</strong><p>${esc(S.company.address)} · ${esc(S.company.phone)}</p><small>Эти реквизиты копируются в новую накладную. Старые накладные сохраняют свои реквизиты.</small></div>`)+
 `<div class="grid-2">${card('Резервное копирование',`<div class="card-body"><p>Выгрузка содержит всю базу: каталоги, рецептуры, партии, документы, заказы и финансы.</p><a class="btn primary" href="/api/backup">↓ Скачать резервную копию</a><p class="help">Копия также сохраняется на серверном компьютере в data/backups. Автоматическая копия создаётся при первом запуске за день. Храните отдельную копию на другом носителе.</p></div>`)}${card('Восстановление',`<div class="card-body"><p>Заменяет текущую базу выбранной копией. Перед заменой программа сохранит текущие данные отдельно.</p><label class="field">Файл .sqlite3<input type="file" id="restore-file" accept=".sqlite3,.db"></label><div id="restore-status" role="status"></div><p id="restore-chosen" class="help" role="status">Копия ещё не выбрана</p><p><input id="restore-confirm" placeholder="Введите ВОССТАНОВИТЬ"></p>${btn('Восстановить базу','restore','danger')}<p class="help">Попросите сотрудников завершить работу перед восстановлением. Лимит загрузки копии — 48 МБ.</p></div>`)}</div>`+
 card('О приложении',`<div class="card-body"><p><strong>Цех · версия 0.5.3</strong> — локальное приложение для кулинарного и кондитерского производства.</p><p class="sub">Схема базы: ${S.schema_version}. Документы проводятся атомарно; отрицательные остатки запрещены. Обмен с 1С отложен. Роли и пароли не предусмотрены; используйте доверенную локальную сеть.</p><p class="help">Для нескольких сотрудников запустите start-network.bat на основном компьютере. На остальных откройте адрес основного компьютера с портом 8765. База хранится только на основном компьютере.</p></div>`);}

// Modal form helpers
let saveHandler=null;
function field(label,name,value='',type='text',extra=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function select(label,name,opts,extra=''){return `<label class="field">${label}<select name="${name}" ${extra}>${opts}</select></label>`;}
function area(label,name,value=''){return `<label class="field wide">${label}<textarea name="${name}">${esc(value)}</textarea></label>`;}
function modal(title,body,handler=null,saveLabel='Сохранить'){
 closeIngredientPicker();saveHandler=handler;$('#modal').classList.remove('recipe-dialog','full-screen');
 $('#modal-content').innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="icon" data-action="close-modal" aria-label="Закрыть">×</button></div><form id="dialog-form"><div class="modal-body">${body}<div id="form-error" role="alert"></div></div><div class="modal-foot">${btn('Закрыть','close-modal')}${handler?`<button class="btn primary" type="submit" id="save-button">${saveLabel}</button>`:''}</div></form>`;
 if(!$('#modal').open)$('#modal').showModal();
 $('#dialog-form').addEventListener('submit',async e=>{e.preventDefault();if(e.currentTarget.dataset.saving)return;e.currentTarget.dataset.saving='1';const form=e.currentTarget;const b=$('#save-button');b.disabled=true;$('#form-error').innerHTML='';try{const printing=e.submitter?.dataset.print==='invoice';const printWindow=printing?window.open('about:blank','_blank'):null;try{const result=await saveHandler(new FormData(e.currentTarget));await refresh();$('#modal').close();toast('Сохранено');if(printWindow)printWindow.location='/api/export?type=document&id='+result.id+'&format=html';}catch(err){printWindow?.close();throw err;}}catch(err){$('#form-error').innerHTML=errHtml(err);$('#form-error').scrollIntoView({block:'nearest'});}finally{b.disabled=false;delete form.dataset.saving;}});
}
const fdObj=fd=>Object.fromEntries(fd.entries());
function staff(){return $('#employee').value.trim();}
function baseDoc(){return field('Дата документа *','date',today(),'date','required')+field('Ответственный *','responsible',staff(),'text','required')+field('Примечание','note');}
function editItem(id){
 const i=item(id)||{kind:'raw',unit:'кг',mode:'stock',shelf_hours:336,track_expiry:false,pack_size:1,losses:[],active:true};
 modal(id?'Карточка номенклатуры':'Новая позиция',`<div class="form-grid">${field('Наименование *','name',i.name,'text','required')}${select('Вид *','kind',Object.entries(kinds).map(([k,v])=>`<option value="${k}" ${i.kind===k?'selected':''}>${v}</option>`).join(''))}${select('Базовая единица *','unit',['кг','л','шт.','уп.'].map(u=>`<option ${i.unit===u?'selected':''}>${u}</option>`).join(''))}${field('Папка (можно через /)','folder',i.folder)}${field('Категория','category',i.category)}${field('Минимальный остаток','minimum',i.minimum||0,'number','min="0" step="any"')}${field('Начальная цена за базовую единицу, ₽','price',i.price||0,'number','min="0" step="0.01"')}${field('Цена продажи за базовую единицу, ₽','sale_price',i.sale_price||0,'number','min="0" step="0.01"')}<label class="checkbox-field"><input type="checkbox" name="track_expiry" ${i.track_expiry?'checked':''}> Учитывать срок годности</label>${field('Срок годности, суток','shelf_days',i.shelf_hours>0?i.shelf_hours/24:14,'number',`min="0.01" step="any" ${i.track_expiry?'required':'disabled'}`)}${select('Учёт полуфабриката','mode',`<option value="stock" ${i.mode==='stock'?'selected':''}>На складе</option><option value="virtual" ${i.mode==='virtual'?'selected':''}>Разложить на сырьё</option>`)}${field('Штук в упаковке (справочно)','pack_size',i.pack_size,'number','min="0.001" step="any"')}${select('Статус','active',`<option value="1" ${i.active?'selected':''}>Активна</option><option value="0" ${!i.active?'selected':''}>В архиве</option>`)}${field('Средний вес порции, кг (для весовых блюд)','portion_weight',i.portion_weight||0,'number','min="0" step="0.001"')}${field('Сдельная расценка за '+esc(i.unit)+', ₽','labor_rate',i.labor_rate||0,'number','min="0" step="0.01"')}${field('Прочие производственные за '+esc(i.unit)+', ₽','overhead_rate',i.overhead_rate||0,'number','min="0" step="0.01"')}${field('Прочие производственные, % от материалов','overhead_percent',i.overhead_percent||0,'number','min="0" step="0.01"')}${field('Производственный запас, %','production_buffer',i.production_buffer||0,'number','min="0" step="0.1"')}${area('Примечание','notes',i.notes)}</div><p class="help">Упаковку и этикетку добавляйте ингредиентами ТТК. Зарплата начисляется по выработке исполнителей. Норматив прочих расходов включается в себестоимость выпуска. Цена приёмки указывается за базовую единицу. Без галочки срок новых партий не обязателен; ранее введённые сроки партий сохраняются. Последняя закупочная цена берётся из документов. Для упаковки складской единицей является целая упаковка; её состав здесь справочный.</p><p class="help">Изменение расценки пересчитает зарплату и себестоимость связанных действующих документов. Суммы счетов клиентов сохраняются.</p><hr class="form-divider"><h3>Нормы потерь по способам обработки</h3><div id="loss-lines"></div>${btn('＋ Способ обработки','add-loss','small')}`,async fd=>{const d=fdObj(fd);d.id=id;d.modified_by=staff();d.active=d.active==='1';d.track_expiry=fd.has('track_expiry');d.losses=$$('.loss-row').map(r=>({name:$('.loss-name',r).value,mechanical:$('.loss-mech',r).value,thermal:$('.loss-heat',r).value}));await api('items',d);});
 i.losses.forEach(addLoss);togglePortionMaster();
}
function addLoss(l={}){$('#loss-lines').insertAdjacentHTML('beforeend',`<div class="toolbar loss-row"><input class="loss-name" placeholder="Запекание / бланширование…" value="${esc(l.name||'')}" required><input class="loss-mech" aria-label="Механические потери" type="number" min="0" max="99.999" step="any" value="${l.mechanical||0}" placeholder="Механические, %"><input class="loss-heat" aria-label="Тепловые потери" type="number" min="0" max="99.999" step="any" value="${l.thermal||0}" placeholder="Тепловые, %">${btn('×','remove-row','small')}</div>`);}
function editPartner(id,kind='client'){
 const p=partner(id)||{kind,payment_days:0,debt_limit:0,reminder:'manager'};
 modal(id?'Карточка контрагента':p.kind==='client'?'Новый клиент':'Новый поставщик',`<p class="help">Обязательное поле отмечено *. ИНН нужен при оформлении реквизитов организации; для управленческого учёта допускается без него.</p><div class="form-grid">${field('Наименование *','name',p.name,'text','required')}${field('ИНН (10 или 12 цифр)','inn',p.inn)}${field('Контактное лицо','contact',p.contact)}${field('Телефон','phone',p.phone,'tel')}${field('Email','email',p.email,'email')}${field('Адрес / адрес доставки','address',p.address)}${p.kind==='client'?field('Менеджер клиента','manager',p.manager)+field('Дни заказа','order_days',p.order_days,'text','placeholder="Пн, Ср, Пт"')+select('Кто инициирует заказ','reminder',`<option value="manager" ${p.reminder==='manager'?'selected':''}>Напомнить менеджеру</option><option value="self" ${p.reminder==='self'?'selected':''}>Клиент звонит сам</option>`):''}${field('Отсрочка оплаты, дней','payment_days',p.payment_days,'number','min="0" step="1"')}${p.kind==='client'?select('Прайс клиента *','price_list_id',S.pricing.lists.map(c=>`<option value="${c.id}" ${c.id===(p.price_list_id||1)?'selected':''}>${esc(c.name)}</option>`).join('')):''}${p.kind==='client'?field('Лимит долга, ₽ (0 — без лимита)','debt_limit',p.debt_limit,'number','min="0" step="0.01"'):''}${area('Примечание','notes',p.notes)}</div>`,async fd=>api('partners',{...fdObj(fd),kind:p.kind,id}));
}
function newReceipt(){
 modal('Приёмка сырья',`<div class="form-grid">${baseDoc()}${select('Поставщик *','partner_id',options(S.partners.filter(p=>p.kind==='supplier')), 'required')}${field('Документ поставщика','supplier_document')}${field('Склад','warehouse','Основной склад')}${field('Кто сдал','handed_by')}</div><hr class="form-divider"><p class="help">Цена за базовую единицу (кг / л / шт. / уп.), даже если количество вводится в граммах.</p><div class="table-wrap"><table class="line-table"><thead><tr><th>Сырьё / упаковка</th><th>Кол-во</th><th>Ед.</th><th>Цена</th><th>Изготовлено</th><th>Годен до</th><th>Партия</th><th></th></tr></thead><tbody id="receipt-lines"></tbody></table></div>${btn('＋ Строка','add-receipt-line','small')}`,async fd=>api('receipt',{...fdObj(fd),lines:$$('#receipt-lines tr').map(r=>({item_id:$('.r-item',r).value,qty:$('.r-qty',r).value,unit:$('.r-unit',r).value,price:$('.r-price',r).value,produced:$('.r-made',r).value,expires:$('.r-exp',r).value,code:$('.r-code',r).value}))}),'Провести приёмку');addReceiptLine();
}
function addReceiptLine(){
 const expires=new Date();expires.setDate(expires.getDate()+7);
 $('#receipt-lines').insertAdjacentHTML('beforeend',`<tr><td><input class="item-search" placeholder="Найти позицию…" aria-label="Поиск позиции"><select class="r-item" required>${catalogOptions(S.items.filter(i=>i.active&&['raw','packaging'].includes(i.kind)))}</select></td><td><input class="r-qty" type="number" min="0.000001" step="any" required></td><td><select class="r-unit narrow">${unitOptions('кг')}</select></td><td><input class="r-price" type="number" min="0" step="0.01" required></td><td><input class="r-made" type="datetime-local" style="width:185px" value="${now()}" required></td><td><input class="r-exp" type="datetime-local" style="width:185px" value="${localDate(expires)}T23:59" required></td><td><input class="r-code" placeholder="Авто"></td><td>${btn('×','remove-row','small')}</td></tr>`);
}
function editRecipe(id){
 const r=S.recipes.find(x=>x.id==id)||{yield_qty:1,lines:[]};
 modal(id?'Новая версия ТТК':'Новая технологическая карта',`<div class="form-grid">${select('Продукция *','item_id',options(S.items.filter(i=>['finished','semi'].includes(i.kind)),r.item_id),'required')}${field('Базовый выход в единице продукции *','yield_qty',r.yield_qty,'number','min="0.000001" step="any" required')}${field('Кто заполнял *','author',staff()||r.author,'text','required')}</div><p>Номер: ${r.id?'ТТК № '+String(r.id).padStart(6,'0'):'присвоится при сохранении'} · Создана: ${r.created?fmtDate(r.created):fmtDate(now())}</p>${btn('На весь экран / свернуть','toggle-fullscreen','small')}<p class="help">«Выход ингредиента» — количество после всех выбранных потерь. Брутто рассчитывается последовательно. Для сырья без обработки потери равны нулю.</p><div class="table-wrap"><table class="line-table"><thead><tr><th>Ингредиент</th><th>Обработка</th><th>Выход</th><th>Мех., %</th><th>Тепл., %</th><th>Брутто</th><th></th></tr></thead><tbody id="recipe-lines"></tbody></table></div>${btn('＋ Ингредиент','add-recipe-line','small')}<div id="recipe-total" class="inline-summary"></div><hr class="form-divider"><div class="form-grid">${area('Технология приготовления','technology',r.technology)}${area('Требования к качеству','quality',r.quality)}${area('Условия хранения и срок годности','storage',r.storage)}</div>`,async fd=>api('recipes',{...fdObj(fd),lines:$$('#recipe-lines tr').map(row=>({item_id:$('.r-item',row).value,net:$('.r-net',row).value,mechanical:$('.r-mech',row).value,thermal:$('.r-heat',row).value,treatment:$('.r-treatment',row).value}))}),'Сохранить версию');
 $('#modal').classList.add('recipe-dialog');(r.lines.length?r.lines:[{}]).forEach(addRecipeLine);recipeTotal();
}
function addRecipeLine(l={}){
 const i=item(l.item_id);
 $('#recipe-lines').insertAdjacentHTML('beforeend',`<tr><td><select class="r-item recipe-source-select" tabindex="-1" aria-hidden="true">${catalogOptions(S.items.filter(i=>i.active||i.id===l.item_id),l.item_id)}</select><button type="button" class="ingredient-button" data-action="choose-ingredient"><span class="ingredient-name">${esc(i?.name||'Выбрать ингредиент…')}</span><small class="r-unit-text">${esc(i?.unit||'')}</small><span>▾</span></button></td><td><select class="r-treatment">${lossOptions(i,l.treatment)}</select></td><td><input class="r-net" type="number" min="0.000001" step="any" value="${l.net||''}" required></td><td><input class="r-mech narrow" type="number" min="0" max="99.999" step="any" value="${l.mechanical||0}" required></td><td><input class="r-heat narrow" type="number" min="0" max="99.999" step="any" value="${l.thermal||0}" required></td><td class="r-gross">—</td><td>${btn('×','remove-row','small')}</td></tr>`);
}
function lossOptions(i,selected=''){const losses=i?.losses||[];return '<option value="">Без обработки</option>'+losses.map(l=>`<option ${l.name===selected?'selected':''}>${esc(l.name)}</option>`).join('')+(selected&&!losses.some(l=>l.name===selected)?`<option selected>${esc(selected)}</option>`:'');}
function recipeTotal(){let sum=0;$$('#recipe-lines tr').forEach(r=>{const i=item($('.r-item',r).value),q=+$('.r-net',r).value,m=+$('.r-mech',r).value,t=+$('.r-heat',r).value;const gross=q/((1-m/100)*(1-t/100));$('.r-gross',r).textContent=Number.isFinite(gross)?num(gross)+' '+(i?.unit||''):'—';sum+=Number.isFinite(gross)?gross*(i?.planned_cost||0):0;});if($('#recipe-total'))$('#recipe-total').textContent='Плановая стоимость рецептуры: '+rub(sum);}
function viewRecipe(id){
 const r=S.recipes.find(x=>x.id==id),i=item(r.item_id);const versions=S.recipes.filter(x=>x.item_id===i.id).sort((a,b)=>b.version-a.version);
 modal(`ТТК · ${esc(i.name)}`,`<div class="actions">${versions.map(v=>btn('Версия '+v.version,'view-recipe','small',`data-id="${v.id}"`)).join('')}</div><p>ТТК № ${String(r.id).padStart(6,'0')} · Создана ${fmtDate(r.created)} · Автор: ${esc(r.author||'Не указан')}</p><div class="actions">${printLink('recipe',r.id,'Печать ТТК')}${btn('На весь экран / свернуть','toggle-fullscreen','small')}</div><p>Базовый выход: <strong>${num(r.yield_qty)} ${esc(i.unit)}</strong></p>${table(['Ингредиент','Обработка','Брутто','Мех. %','Тепл. %','Выход','Стоимость'],r.lines.map(l=>`<tr><td>${esc(l.name)}</td><td>${esc(l.treatment||'—')}</td><td>${num(l.gross)} ${esc(l.unit)}</td><td>${num(l.mechanical)}</td><td>${num(l.thermal)}</td><td>${num(l.net)}</td><td>${rub(l.gross*item(l.item_id).planned_cost)}</td></tr>`))}<div class="inline-summary">Стоимость рецептуры: ${rub(r.lines.reduce((s,l)=>s+l.gross*item(l.item_id).planned_cost,0))}. Цены — текущие последние закупочные.</div><p><strong>Технология:</strong> ${esc(r.technology)}</p><p><strong>Качество:</strong> ${esc(r.quality)}</p><p><strong>Хранение:</strong> ${esc(r.storage)}</p><h3>Технологическая карта</h3>${exportButtons('recipe',r.id)}<br><h3>Калькуляционная карта</h3>${exportButtons('calculation',r.id)}`);$('#modal').classList.add('recipe-dialog');
}
function newProduction(id,qty=1,jobId=null){
 modal('Выпуск продукции на склад',`<div class="notice green">Выпуск приходует готовую партию и списывает сырьё, упаковку и этикетку по ТТК. Выработку распределите между исполнителями в базовой единице продукции.</div><div class="form-grid">${baseDoc()}${select('Продукция *','item_id',catalogOptions(sellable(),id),'required')}${field('Фактический выпуск *','qty',qty,'number','min="0.000001" step="any" required')}${select('Единица ввода','unit',unitOptions(item(id)?.unit||'кг'))}${field('Плановый выпуск','planned_qty',qty,'number','min="0.000001" step="any"')}${field('Дата и время изготовления *','produced',now(),'datetime-local','required')}${field('Годен до (пусто — из карточки)','expires','','datetime-local')}${field('Номер партии (пусто — автоматически)','code')}${field('Основание','basis',jobId?'По наряду № '+jobId:'На свободный склад')}${field('Склад готовой продукции','warehouse','Основной склад')}</div><h3>Кто производил продукцию</h3><p class="help">Расценка берётся из карточки продукции. Сумма выработки должна совпасть с фактическим выпуском. При нулевой расценке исполнители необязательны.</p>${S.employees.some(e=>e.active)?table(['Сотрудник','Выработка','Ед.',''],[]).replace('<tbody></tbody>','<tbody id="worker-lines"></tbody>'):'<p class="notice">Сначала добавьте исполнителей в разделе «Сотрудники и выработка».</p><table><tbody id="worker-lines"></tbody></table>'}${btn('＋ Исполнитель','add-worker','small')}<div id="production-preview" class="inline-summary"></div>`,async fd=>{const d=fdObj(fd);if(!d.expires)delete d.expires;return api('production',{...d,job_id:jobId,workers:$$('.worker-line').filter(r=>$('.worker-person',r).value).map(r=>({employee_id:$('.worker-person',r).value,qty:$('.worker-qty',r).value}))});},'Провести выпуск');if(S.employees.some(e=>e.active))addWorker({qty});productionPreview();
}
function productionPreview(){
 if(!$('#production-preview'))return;const i=item($('[name=item_id]',$('#modal')).value);if(!i)return;const expiry=$('[name=expires]',$('#modal'));if(expiry){expiry.disabled=!i.track_expiry;if(!i.track_expiry)expiry.value='';}
 let q=+$('[name=qty]',$('#modal')).value;const unit=$('[name=unit]',$('#modal')).value;
 if((unit==='г'&&i.unit==='кг')||(unit==='мл'&&i.unit==='л'))q/=1000;
 else if(unit!==i.unit){$('#production-preview').textContent='Проверьте единицу измерения';return;}
 const needs={};function expand(iid,amount,path=[]){if(path.includes(iid))throw Error('Циклическая рецептура');const r=S.recipes.filter(r=>r.item_id===iid).sort((a,b)=>b.version-a.version)[0];if(!r)throw Error('Нет ТТК: '+item(iid).name);for(const l of r.lines){const child=item(l.item_id),n=l.gross*amount/r.yield_qty;if(child.mode==='virtual')expand(child.id,n,[...path,iid]);else needs[child.id]=(needs[child.id]||0)+n;}}
 try{expand(i.id,q);$('#production-preview').innerHTML='<strong>Сырьё к списанию (предварительно)</strong><br>'+Object.entries(needs).map(([id,n])=>{const x=item(id);if(['шт.','уп.'].includes(x.unit))n=Math.ceil(n-1e-7);return `${esc(x.name)}: ${num(n)} ${esc(x.unit)} · доступно ${num(x.available)} ${n>x.available?'<span class="text-red">— недостаточно</span>':''}`;}).join('<br>');}catch(e){$('#production-preview').textContent=e.message;}
}
