 modal(id?'Изменить заказ':'Новый заказ клиента',`<div class="form-grid">${select('Клиент *','client_id',options(S.partners.filter(p=>p.kind==='client'),o.client_id),'required')}${field('Дата и время отгрузки *','due',o.due||localDate(tomorrow)+'T10:00','datetime-local','required')}${field('Менеджер *','manager',o.manager||staff(),'text','required')}${area('Примечание','note',o.note)}${deliveryFields(o)}</div><hr class="form-divider"><div class="table-wrap"><table class="line-table"><thead><tr><th>Продукция</th><th>Заказано</th><th>Ед.</th><th>Цена</th><th>Допуск, %</th><th></th></tr></thead><tbody id="order-lines"></tbody></table></div>${btn('＋ Позиция','add-order-line','small')}${btn('Обновить цены по прайсу','order-reprice','small')}<div id="order-summary" class="inline-summary"></div><p class="help">Показан годный остаток на дату отгрузки и потребность других заказов до этой даты. Годные партии распределяются между заказами по очереди доставки. Окончательная проверка остатка выполняется при отгрузке.</p>`,async fd=>api('orders',{...fdObj(fd),id,price_token:S.pricing.token,lines:$$('#order-lines tr').map(r=>({price_mode:r.dataset.priceMode||'auto',item_id:$('.r-item',r).value,qty:$('.r-qty',r).value,unit:$('.r-unit',r).value,price:$('.r-price',r).value,tolerance:$('.r-tol',r).value,order_mode:$('.r-unit',r).value==='порц.'?'portions':'quantity',portions:$('.r-unit',r).value==='порц.'?$('.r-qty',r).value:0,portion_weight:$('.r-portion-weight',r)?.value||0}))}));
