function orderSummary(){if(!$('#order-summary'))return;let sum=0,hasPortions=false;const due=$('[name=due]',$('#modal')).value;$$('#order-lines tr').forEach(r=>{const i=item($('.r-item',r).value);let q=+$('.r-qty',r).value;const u=$('.r-unit',r).value;const portions=u==='порц.';let hint='';if(portions){hasPortions=true;const count=q,weight=+$('.r-portion-weight',r).value;q*=weight;hint=`${num(count)} порц. × ${num(weight)} кг = ориентировочно ${num(q)} кг<br>`;if(!weight)hint='<span class="text-red">Укажите средний вес порции в карточке или в строке заказа.</span><br>';}else if((u==='г'&&i?.unit==='кг')||(u==='мл'&&i?.unit==='л'))q/=1000;sum+=q*Number($('.r-price',r).value);if(i){const info=quantityInfo(i,due);$('.r-stock',r).innerHTML=hint+`Годно к дате: ${num(info.available)} ${esc(i.unit)} · в заказах: ${num(info.demand)} · свободно: ${num(info.free)}${info.first?'<br>Первая партия: '+esc(info.first.code)+' · изготовлено '+fmtDate(info.first.produced)+' · годен до '+expiryDate(info.first.expires):''}${q>info.free?'<br><span class="text-red">Требуется производство</span>':''}`;}});$('#order-summary').textContent=(hasPortions?'Предварительная сумма по ориентировочному весу: ':'Предварительная сумма заказа: ')+rub(sum);}
