function catalogOptions(items,selected){const groups={};for(const i of items){const key=[kinds[i.kind],i.folder,i.category].filter(Boolean).join(' / ');(groups[key]??=[]).push(i);}return '<option value="">Выберите…</option>'+Object.keys(groups).sort().map(k=>`<optgroup label="${esc(k)}">${groups[k].sort((a,b)=>a.name.localeCompare(b.name,'ru')).map(i=>`<option value="${i.id}" ${i.id==selected?'selected':''}>${esc(i.name)}</option>`).join('')}</optgroup>`).join('');}
