function payroll(){
 const f=filters.payroll||{};const start=f.from||report.from,end=f.to||today();const work=effectiveDocs().filter(d=>d.kind==='production'&&d.date>=start&&d.date<=end).flatMap(d=>(d.data.workers||[]).map(w=>({...w,date:d.date,document_id:d.id,product:d.data.name}))).filter(w=>!f.employee||w.employee_id==f.employee);
 const total=work.reduce((a,w)=>a+w.amount,0);const extra=`&from=${start}&to=${end}${f.employee?'&employee_id='+f.employee:''}`;
 const balances=S.employees.map(e=>{const accrued=effectiveDocs().filter(d=>d.kind==='production').flatMap(d=>d.data.workers||[]).filter(w=>w.employee_id===e.id).reduce((a,w)=>a+w.amount,0);const paid=effectiveDocs().filter(d=>d.kind==='expense'&&d.data.employee_id===e.id&&d.data.already_in_cost).reduce((a,d)=>a+d.total,0);return {...e,accrued,paid};});
 return pageTop('Сотрудники и выработка','Изменение расценки карточки пересчитывает начисления связанных выпусков. Отменённые выпуски исключены.',btn('＋ Сотрудник','new-employee','primary')+btn('Выплата зарплаты','new-expense')+btn('Пересчитать начисления','recalculate-costs'))+`<div class="toolbar"><label class="field">С даты<input type="date" data-filter="payroll.from" value="${start}"></label><label class="field">По дату<input type="date" data-filter="payroll.to" value="${end}"></label><select data-filter="payroll.employee">${options(S.employees,f.employee,'Все сотрудники')}</select></div>`+(effectiveDocs().some(d=>d.kind==='production'&&d.data.pending_workers)?card('Нужно назначить исполнителей',documentRows(effectiveDocs().filter(d=>d.kind==='production'&&d.data.pending_workers))):'')+card('Начислено за период: '+rub(total),work.length?table(['Дата / выпуск','Сотрудник','Продукция','Выработка','Расценка','Начислено'],work.map(w=>`<tr><td>${fmtDate(w.date)}<small>Выпуск № ${w.document_id}</small></td><td>${esc(w.name)}</td><td>${esc(w.product)}</td><td>${num(w.qty)} ${esc(w.unit)}</td><td>${rub(w.rate)} / ${esc(w.unit)}</td><td>${rub(w.amount)}</td></tr>`)):empty('Выработки за период нет','В документе выпуска укажите сотрудников и распределите фактическое количество.'),exportButtons('payroll','',extra))+card('Сотрудники и расчёты за всё время',table(['ФИО','Начислено','Выплачено','К выплате',''],balances.map(e=>`<tr><td>${esc(e.name)}${!e.active?badge('В архиве','gray'):''}</td><td>${rub(e.accrued)}</td><td>${rub(e.paid)}</td><td>${e.accrued<e.paid?badge('Переплата '+rub(e.paid-e.accrued),'amber'):rub(e.accrued-e.paid)}</td><td>${btn('Изменить','edit-employee','small',`data-id="${e.id}"`)}</td></tr>`)));
}
