function newExchange(id){const d=S.documents.find(x=>x.id===id);modal('Физобмен по счёту № '+id,`<div class="notice">Возвращённая продукция попадёт в карантин. Замена спишется со склада; долг клиента останется прежним. Если нужна доплата или уменьшение долга, оформите возврат и новую отгрузку.</div><div class="form-grid">${baseDoc()}${field('Причина обмена *','reason','','text','required')}</div><h3>Принимаем от клиента</h3>${table(['Продукция','Отгружено','Количество к обмену'],d.data.lines.map(l=>`<tr class="exchange-in" data-id="${l.line_id}"><td>${esc(l.name)}</td><td>${num(l.qty)} ${esc(l.unit)}</td><td><input class="exchange-qty" type="number" min="0" step="any" value="0"></td></tr>`))}<h3>Выдаём замену</h3>${table(['Продукция','Количество','Ед.',''],[]).replace('<tbody></tbody>','<tbody id="replacement-lines"></tbody>')}${btn('＋ Позиция замены','add-replacement','small')}`,fd=>api('exchange',{...fdObj(fd),shipment_id:id,lines:$$('.exchange-in').filter(r=>+$('.exchange-qty',r).value>0).map(r=>({line_id:+r.dataset.id,qty:$('.exchange-qty',r).value})),replacements:$$('.replacement-line').map(r=>({item_id:$('.replacement-item',r).value,qty:$('.replacement-qty',r).value}))}),'Провести физобмен');addReplacement(d.data.lines[0]?.item_id);}
