function fullCostReport(docs){
 const all=effectiveDocs();const rows=docs.filter(d=>d.kind==='shipment').map(d=>{const allocated=all.filter(e=>e.kind==='expense'&&!e.data.already_in_cost).reduce((sum,e)=>sum+(e.data.allocations||[]).filter(a=>a.document_id===d.id).reduce((s,a)=>s+a.amount,0),0);const returned=all.filter(r=>r.kind==='return'&&r.data.shipment_id===d.id);const revenue=d.total-returned.reduce((s,r)=>s+r.total,0),production=d.cost-returned.reduce((s,r)=>s+r.cost,0);const exchanges=all.filter(r=>r.kind==='exchange'&&r.data.shipment_id===d.id).reduce((s,r)=>s+r.cost,0);return {d,allocated,revenue,production,exchanges};});
 return card('Полная себестоимость продаж',rows.length?table(['Счёт / клиент','Выручка с возвратами','Производственная стоимость','Распределённые расходы','Физобмены, изменение стоимости','Полная стоимость','Результат'],rows.map(r=>`<tr><td>№ ${r.d.id}<small>${esc(r.d.data.client_name)}</small></td><td>${rub(r.revenue)}</td><td>${rub(r.production)}</td><td>${rub(r.allocated)}</td><td>${rub(r.exchanges)}</td><td>${rub(r.production+r.allocated+r.exchanges)}</td><td>${rub(r.revenue-r.production-r.allocated-r.exchanges)}</td></tr>`)):empty('Нет отгрузок за период'),exportButtons('fullcost','',`&from=${report.from}&to=${report.to}`))+`<p class="help">Производственная стоимость включает сырьё, упаковку, сдельную зарплату и норматив прочих расходов. Фактическая логистика распределяется документом расхода. Выплаты уже начисленной зарплаты не уменьшают результат повторно. Полная стоимость счетов показана с последующими возвратами и расходами за всё время; показатели периода выше относятся к датам операций.</p>`;
}

let ingredientTarget=null;
function closeIngredientPicker(){document.getElementById('ingredient-picker')?.remove();ingredientTarget=null;}
function openIngredientPicker(button){
 closeIngredientPicker();ingredientTarget=button.closest('tr');const selected=$('.r-item',ingredientTarget).value;const productId=$('[name=item_id]',$('#modal'))?.value;
 const root={children:{},items:[]};for(const i of S.items.filter(i=>i.active&&i.id!=productId)){let n=root;for(const part of [kinds[i.kind],...i.folder.split('/').map(s=>s.trim()).filter(Boolean),...(i.category?[i.category]:[])])n=n.children[part]??={children:{},items:[]};n.items.push(i);}
 const current=item(selected);const selectedPath=current?[kinds[current.kind],...current.folder.split('/').map(s=>s.trim()).filter(Boolean),...(current.category?[current.category]:[])]:[];
 function tree(node,path=[]){return Object.entries(node.children).sort(([a],[b])=>a.localeCompare(b,'ru')).map(([name,child])=>{const p=[...path,name],open=p.length===1||p.every((x,n)=>selectedPath[n]===x);return `<details ${open?'open':''}><summary>📁 ${esc(name)}</summary>${tree(child,p)}</details>`;}).join('')+node.items.sort((a,b)=>a.name.localeCompare(b.name,'ru')).map(i=>`<button type="button" class="ingredient-choice ${i.id==selected?'selected':''}" data-action="select-ingredient" data-id="${i.id}"><span>${esc(i.name)}</span><small>${esc(i.unit)}</small></button>`).join('');}
 $('#modal').insertAdjacentHTML('beforeend',`<div id="ingredient-picker"><div class="ingredient-backdrop" data-action="close-picker"></div><section class="ingredient-panel" role="dialog" aria-modal="true" aria-label="Выбор ингредиента"><div class="ingredient-head"><h3>Выберите сырьё или полуфабрикат</h3>${btn('×','close-picker','small','aria-label="Закрыть дерево"')}</div><div class="ingredient-tree">${tree(root)}</div></section></div>`);
 $('.ingredient-panel button')?.focus();
}
function selectIngredient(id){const row=ingredientTarget;if(!row)return;const i=item(id),select=$('.r-item',row);if(!i)return;select.value=i.id;$('.ingredient-name',row).textContent=i.name;closeIngredientPicker();select.dispatchEvent(new Event('change',{bubbles:true}));$('.ingredient-button',row).focus();}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#ingredient-picker')){e.preventDefault();e.stopPropagation();const row=ingredientTarget;closeIngredientPicker();$('.ingredient-button',row)?.focus();}},true);
const selectedOrders=new Set();
function updateOrderSelection(){const count=$('#selected-orders-count');if(count)count.textContent='Выбрано заказов: '+selectedOrders.size;const b=$('[data-action="new-dispatch-summary"]');if(b)b.disabled=!selectedOrders.size;const boxes=$$('.order-select');const all=$('#orders-select-all');if(all){all.checked=!!boxes.length&&boxes.every(b=>b.checked);all.indeterminate=boxes.some(b=>b.checked)&&!all.checked;}}
function newDispatchSummary(){const ids=[...selectedOrders].filter(id=>S.orders.some(o=>o.id===id&&o.status!=='deleted'));if(!ids.length)throw Error('Отметьте заказы галочками');modal('Сводная ведомость к отгрузке',`<div class="form-grid">${baseDoc()}${select('Количество для ведомости','mode','<option value="remaining">Неотгруженный остаток заказов</option><option value="ordered">Полное количество заказов</option>')}</div><p>Выбранные заказы: ${ids.map(id=>'№ '+id+' · '+esc(partner(S.orders.find(o=>o.id===id).client_id)?.name)).join('; ')}</p><p class="help">Одинаковые товары суммируются в базовых единицах. Ведомость сохраняет план на момент создания и содержит расшифровку по покупателям. Формирование ведомости не списывает остатки и не закрывает заказы.</p>`,fd=>api('dispatch-summary',{...fdObj(fd),order_ids:ids}),'Сформировать ведомость');$('.modal-foot').insertAdjacentHTML('afterbegin','<button type="submit" class="btn" data-print="invoice">Сформировать и печатать ведомость</button>');}
async function deleteDocument(id){return confirmDeletion(id,false);}
async function deleteOrder(id){return confirmDeletion(id,true);}
async function confirmDeletion(id,order){
 const preview=await api('deletion-preview',order?{order_id:id}:{document_id:id}),cascade=preview.dependents.length>0;
 const label=order?'заказа':'документа';
 modal('Удаление '+label+' № '+id,`${cascade?'<div class="notice">У '+label+' есть зависимые документы. Удалить также все зависимые документы? При «Да» вся показанная цепочка будет удалена с отменой складских и денежных операций. При «Нет» ничего не изменится.</div>'+table(['Документ','Дата','Ответственный','Сумма'],preview.documents.map(d=>`<tr><td>${esc(docKinds[d.kind])} № ${d.id}</td><td>${fmtDate(d.date)}</td><td>${esc(d.responsible)}</td><td>${rub(d.total)}</td></tr>`)):'<div class="notice">Запись исчезнет из рабочего журнала. Складские и денежные операции будут отменены; история удаления сохранится.</div>'}<div class="form-grid">${field('Ответственный *','responsible',staff(),'text','required')}${field('Причина удаления *','reason','','text','required')}</div>`,fd=>api(order?'delete-order':'delete-document',{...fdObj(fd),...(order?{id}:{document_id:id}),cascade,expected_token:preview.token}),cascade?'Да, удалить все':order?'Удалить заказ':'Удалить документ');
 if(cascade)$('#modal .modal-foot [data-action="close-modal"]').textContent='Нет';
}
function editProductionWorkers(id){const d=S.documents.find(d=>d.id===id),i=item(d.data.item_id);modal('Исполнители выпуска № '+id,`<p><strong>${esc(d.data.name)}</strong> · Выпущено ${num(d.data.qty)} ${esc(d.data.unit)} · Текущая расценка ${rub(i.labor_rate)} / ${esc(i.unit)}</p><div class="form-grid"><input type="hidden" name="item_id" value="${i.id}">${field('Ответственный за исправление *','responsible',staff(),'text','required')}${field('Причина исправления *','reason','Уточнение исполнителей и начислений','text','required')}</div>${table(['Сотрудник','Выработка','Ед.',''],[]).replace('<tbody></tbody>','<tbody id="worker-lines"></tbody>')}${btn('＋ Исполнитель','add-worker','small')}<p class="help">Сумма выработки должна равняться выпуску. Начисления и связанная себестоимость пересчитаются автоматически. Количества и суммы счетов сохраняются.</p>`,fd=>api('production-workers',{...fdObj(fd),document_id:id,workers:$$('.worker-line').filter(r=>$('.worker-person',r).value).map(r=>({employee_id:$('.worker-person',r).value,qty:$('.worker-qty',r).value}))}),'Сохранить и пересчитать');const workers=d.data.workers||[];(workers.length?workers:[{qty:d.data.qty}]).forEach(addWorker);}
function recalculateCosts(){modal('Пересчёт зарплаты и себестоимости',`<p>Будут применены текущие расценки и производственные нормы карточек ко всем действующим выпускам. Пересчитаются связанные партии, отгрузки, возвраты, списания и отчёты. Суммы счетов клиентов и складские количества сохраняются. Предыдущие значения останутся в истории.</p><div class="form-grid">${field('Ответственный *','responsible',staff(),'text','required')}${field('Причина *','reason','Пересчёт по текущим карточкам','text','required')}</div>`,fd=>api('recalculate',fdObj(fd)),'Пересчитать');}
function costHistory(id){const d=S.documents.find(d=>d.id===id);modal('История изменений № '+id,table(['Дата','Кто изменил','Причина','Предыдущая стоимость','Прежняя расценка'],(d.data.cost_history||[]).map(h=>`<tr><td>${fmtDate(h.at)}</td><td>${esc(h.responsible)}</td><td>${esc(h.reason)}</td><td>${rub(h.previous_cost)}</td><td>${h.previous_labor_rate===null?'—':rub(h.previous_labor_rate)}</td></tr>`))+(d.data.worker_history?.length?'<h3>Исправления исполнителей</h3>'+table(['Дата','Кто исправил','Причина','Прежняя выработка'],d.data.worker_history.map(h=>`<tr><td>${fmtDate(h.at)}</td><td>${esc(h.responsible)}</td><td>${esc(h.reason)}</td><td>${h.previous_workers.map(w=>esc(w.name)+': '+num(w.qty)+' '+esc(w.unit)).join('<br>')||'Не назначены'}</td></tr>`)):''));}

function togglePortionMaster(){const input=$('[name=portion_weight]',$('#modal'));if(!input)return;const unit=$('[name=unit]',$('#modal'))?.value,kind=$('[name=kind]',$('#modal'))?.value,mode=$('[name=mode]',$('#modal'))?.value;const enabled=unit==='кг'&&['finished','semi'].includes(kind)&&mode!=='virtual';input.closest('label').hidden=!enabled;input.disabled=!enabled;}
function setOrderMode(r){const part=$('.r-unit',r).value==='порц.';const weight=$('.r-portion-weight',r);$('.portion-weight-label',r).hidden=!part;weight.disabled=!part;weight.required=part;$('.r-qty',r).step=part?'1':'any';$('.r-qty',r).min=part?'1':'0.000001';$('.r-tol',r).disabled=part;$('.r-tol',r).required=!part;}
function configureOrderRow(r){const i=item($('.r-item',r).value);if(!i)return;$('.r-unit',r).innerHTML=unitOptions(i.unit)+(i.unit==='кг'?'<option>порц.</option>':'');$('.r-portion-weight',r).value=i.portion_weight||0;$('.r-price-unit',r).textContent='₽ / '+i.unit;setOrderMode(r);}
function expenseTable(rows){return rows.length?table(['Дата / документ','Статья','На что потрачено / кому оплачено','Сумма',''],rows.map(d=>`<tr><td>${fmtDate(d.date)}<small>№ ${d.id}</small></td><td>${esc(d.category)}</td><td class="expense-purpose"><button type="button" class="text-button" data-action="inspect-document" data-id="${d.id}">${esc(d.purpose)}</button><small>${esc(d.recipient)}</small></td><td>${rub(d.amount)}${d.already_in_cost?'<small>Выплата начисленной зарплаты</small>':''}</td><td>${btn('Открыть','inspect-document','small',`data-id="${d.id}"`)} ${btn('Удалить','delete-document','small danger',`data-id="${d.id}"`)}</td></tr>`)):empty('Расходов за период нет');}
function expenseCategory(category){const f=filters.finance||{},start=f.from||report.from,end=f.to||today();const rows=effectiveDocs().filter(d=>d.kind==='expense'&&d.date>=start&&d.date<=end&&(!category||d.data.category===category)).map(d=>({id:d.id,date:d.date,category:d.data.category,purpose:d.data.purpose||d.note||'Назначение не указано',recipient:d.data.recipient||d.data.employee_name||'',amount:d.total,already_in_cost:!!d.data.already_in_cost}));modal(category?'Расходы: '+esc(category):'Все расходы за период',`<p>${fmtDate(start)} — ${fmtDate(end)} · Итого ${rub(rows.reduce((s,d)=>s+d.amount,0))}</p>${expenseTable(rows)}`);}

// Delegated events keep dynamic pages and dialogs consistent.
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const id=+b.dataset.id;try{
 switch(b.dataset.action){case 'price-new':priceColumn();break;case 'price-column':priceColumn(id);break;case 'price-cell':editPriceCell(id,+b.dataset.list);break;case 'price-fill':priceFill();break;case 'price-preview':await previewPrices();break;case 'price-toggle':{const key=b.dataset.key;if(priceCollapsed.has(key))priceCollapsed.delete(key);else priceCollapsed.add(key);await render();break;}case 'price-expand':priceCollapsed.clear();await render();break;case 'price-collapse':$$('.price-group [data-key]').forEach(b=>priceCollapsed.add(b.dataset.key));await render();break;case 'order-apply-prices':updateOrderPrices();$('#order-price-preview')?.remove();break;case 'order-cancel-prices':$('#order-price-preview')?.remove();break;case 'order-reprice':await previewOrderPrices();break;case 'inspect-document':await viewDocument(id);break;case 'expense-category':expenseCategory(b.dataset.category||null);break;case 'financial-report':filters.finance={...filters.finance,from:report.from,to:report.to};navigate('finance');break;case 'choose-ingredient':openIngredientPicker(b);break;case 'close-picker':closeIngredientPicker();break;case 'select-ingredient':selectIngredient(id);break;case 'new-dispatch-summary':newDispatchSummary();break;case 'clear-order-selection':selectedOrders.clear();await render();break;case 'delete-document':await deleteDocument(id);break;case 'delete-order':await deleteOrder(id);break;case 'edit-production-workers':editProductionWorkers(id);break;case 'recalculate-costs':recalculateCosts();break;case 'cost-history':costHistory(id);break;case 'toggle-fullscreen':$('#modal').classList.toggle('full-screen');break;case 'tree-expand':setTreeOpen(true);break;case 'tree-collapse':setTreeOpen(false);break;case 'new-employee':editEmployee();break;case 'edit-employee':editEmployee(id);break;case 'add-worker':addWorker();break;case 'new-job':createJob();break;case 'plan-day':planDate=b.dataset.date;await render();break;case 'close-job':closeJob(id);break;case 'review-job':reviewJob(id);break;case 'view-job-history':jobHistory(id);break;case 'new-exchange':newExchange(id);break;case 'add-replacement':addReplacement();break;case 'new-refund':newRefund();break;case 'close-modal':$('#modal').close();break;case 'new-item':editItem();break;case 'edit-item':editItem(id);break;case 'add-loss':addLoss();break;case 'remove-row':b.closest('tr,.loss-row').remove();recipeTotal();orderSummary();break;case 'new-partner':editPartner(null,b.dataset.kind);break;case 'edit-partner':editPartner(id);break;case 'partner-tab':filters.partners={...filters.partners,kind:b.dataset.kind};render();break;case 'new-receipt':newReceipt();break;case 'add-receipt-line':addReceiptLine();break;case 'new-recipe':editRecipe();break;case 'edit-recipe':editRecipe(id);break;case 'view-recipe':viewRecipe(id);break;case 'add-recipe-line':addRecipeLine();break;case 'new-production':newProduction(id||undefined,+b.dataset.qty||1,+b.dataset.job||null);break;case 'new-order':editOrder();break;case 'edit-order':editOrder(id);break;case 'add-order-line':addOrderLine();break;case 'view-order':viewOrder(id);break;case 'new-shipment':newShipment(id);break;case 'new-payment':newMoney('payment');break;case 'new-expense':newMoney('expense');break;case 'new-writeoff':newWriteoff(id);break;case 'new-inventory':newInventory();break;case 'view-document':viewDocument(id);break;case 'close-order':modal('Закрытие заказа',`<div class="form-grid">${field('Ответственный *','responsible',staff(),'text','required')}${field('Причина закрытия *','reason','','text','required')}</div>`,async fd=>api('close-order',{...fdObj(fd),id}),'Закрыть заказ');break;case 'reverse-document':reverseDocument(id);break;case 'new-return':newReturn(id);break;case 'release-lot':releaseLot(id);break;case 'new-driver':editDriver();break;case 'edit-driver':editDriver(id);break;case 'assign-delivery':assignDelivery(id);break;case 'edit-company':editCompany();break;case 'close-day':closeDay();break;case 'restore':b.disabled=true;try{await restore();}finally{b.disabled=false;}break;}
 }catch(err){toast(err.message);}});
let filterTimer;
document.addEventListener('input',e=>{
 const t=e.target;if(t.matches('#order-lines .r-price')){$('#order-price-preview')?.remove();const row=t.closest('tr');row.dataset.priceMode='manual';t.setCustomValidity('');const note=$('.r-price-note',row);if(note)note.textContent='Цена изменена вручную';}if(t.matches('.item-search')){const sel=$('select.r-item',t.parentElement);for(const opt of sel.options)opt.hidden=!!opt.value&&!opt.selected&&!opt.textContent.toLowerCase().includes(t.value.toLowerCase());}if(t.matches('[data-filter]')&&t.tagName==='INPUT'&&!['date','checkbox'].includes(t.type)){clearTimeout(filterTimer);filterTimer=setTimeout(async()=>{const [p,k]=t.dataset.filter.split('.');filters[p]={...filters[p],[k]:t.value};const pos=t.selectionStart;await render();const input=$(`[data-filter="${p}.${k}"]`);input?.focus();input?.setSelectionRange(pos,pos);},220);}
 if(t.closest('#recipe-lines'))recipeTotal();if(t.closest('#order-lines'))orderSummary();if(t.closest('.ship-line')||t.name==='discount_percent')shipmentTotal();if(t.closest('#modal')&&['qty','unit'].includes(t.name))productionPreview();
});
document.addEventListener('change',async e=>{const t=e.target;try{if(t.classList.contains('price-select')){const id=+t.dataset.id;if(t.checked)priceSelection.add(id);else priceSelection.delete(id);$('#price-selected').textContent='Выбрано: '+priceSelection.size;}if(t.id==='price-select-all'){for(const i of priceProducts()){if(t.checked)priceSelection.add(i.id);else priceSelection.delete(i.id);}await render();}if(t.classList.contains('order-select')){const id=+t.dataset.id;if(t.checked)selectedOrders.add(id);else selectedOrders.delete(id);updateOrderSelection();}if(t.id==='orders-select-all'){$$('.order-select').forEach(c=>{c.checked=t.checked;if(c.checked)selectedOrders.add(+c.dataset.id);else selectedOrders.delete(+c.dataset.id);});updateOrderSelection();}
 if(t.id==='restore-file'){$('#restore-status').textContent='';restorePicking=false;const f=t.files[0];$('#restore-chosen').textContent=f?'Выбрана копия: '+f.name+' · '+num(f.size/1024)+' КБ':'Копия ещё не выбрана';}
 if(t.matches('[data-filter]')&&(t.tagName==='SELECT'||t.type==='date'||t.type==='checkbox')){const [p,k]=t.dataset.filter.split('.');filters[p]={...filters[p],[k]:t.type==='checkbox'?(t.checked?'1':''):t.value};await render();}
 if(t.id==='logistics-date'){logisticsDate=t.value||today();await render();}
 if(t.id==='logistics-driver'){logisticsDriver=t.value;await render();}
 if(['kind','unit','mode'].includes(t.name))togglePortionMaster();if(t.name==='track_expiry'){const input=$('[name=shelf_days]',$('#modal'));input.disabled=!t.checked;input.required=t.checked;}
 if(t.id==='plan-date'){planDate=t.value||today();await render();}
 if(t.id==='report-from'||t.id==='report-to'||t.id==='report-group'){report[t.id.slice(7)]=t.value;localStorage.setItem('ceh.report',JSON.stringify(report));await render();}
 if(t.dataset.column){report.columns=t.checked?[...report.columns,t.dataset.column]:report.columns.filter(k=>k!==t.dataset.column);localStorage.setItem('ceh.report',JSON.stringify(report));await render();}
 if(t.matches('.r-item')){if(t.closest('#order-lines'))$('#order-price-preview')?.remove();const r=t.closest('tr'),i=item(t.value);if(!i)return;
  if($('.r-unit',r))$('.r-unit',r).value=i.unit;
  if($('.r-price',r))$('.r-price',r).value=r.closest('#receipt-lines')?i.planned_cost:i.sale_price;
  if($('.r-exp',r)){const input=$('.r-exp',r);input.disabled=!i.track_expiry;input.required=!!i.track_expiry;if(!i.track_expiry)input.value='';else if(!input.value){const d=new Date();d.setHours(d.getHours()+(i.shelf_hours||24));input.value=localDate(d)+'T'+String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0');}}
  if($('.r-treatment',r)){$('.r-treatment',r).innerHTML=lossOptions(i);$('.r-unit-text',r).textContent=i.unit;$('.r-mech',r).value=0;$('.r-heat',r).value=0;}
  if(r.closest('#order-lines')){configureOrderRow(r);orderPrice(r);}recipeTotal();orderSummary();
 }
 if(t.matches('.r-treatment')){const r=t.closest('tr'),l=item($('.r-item',r).value)?.losses.find(l=>l.name===t.value);$('.r-mech',r).value=l?.mechanical||0;$('.r-heat',r).value=l?.thermal||0;recipeTotal();}
 if(t.name==='item_id'&&$('#production-preview')){const i=item(t.value);if(i){$('[name=unit]',$('#modal')).value=i.unit;const exp=$('[name=expires]',$('#modal'));exp.disabled=!i.track_expiry;if(!i.track_expiry)exp.value='';}productionPreview();}
 if(t.name==='client_id'&&$('#order-lines')){$('#order-price-preview')?.remove();updateOrderPrices();const p=partner(t.value);if(p?.manager)$('[name=manager]',$('#modal')).value=p.manager;for(const [field,key] of [['delivery_address','address'],['delivery_phone','phone'],['delivery_contact','contact']]){const input=$(`[name=${field}]`,$('#modal'));if(input)input.value=p?.[key]||'';}}
 if(t.name==='due')orderSummary();if(t.matches('#order-lines .r-unit')){setOrderMode(t.closest('tr'));orderSummary();}if(t.name==='item_id'&&$('#worker-lines')){const it=item(t.value);for(const r of $$('.worker-line'))$('.worker-unit',r).textContent=it?.unit||'';}if(t.matches('.replacement-item')){$('.replacement-unit',t.closest('tr')).textContent=item(t.value)?.unit||'';}
 }catch(err){toast(err.message);}});
try{const saved=JSON.parse(localStorage.getItem('ceh.report'));if(saved&&['product','client','day'].includes(saved.group)&&Array.isArray(saved.columns))report={...report,...saved,columns:saved.columns.filter(k=>['qty','revenue','cost','profit'].includes(k))};}catch{}
